// Jev (TypeSafe System One) review of the rebase/refactor closeout.
// Usage: node jev-check.mjs <repoRoot>
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join } from 'node:path';

const repo = process.argv[2];
const env = readFileSync(join(repo, '.env'), 'utf8');
const key = env.match(/^TYPESAFE_API_KEY=(.*)$/m)?.[1]?.trim().replace(/^['"]|['"]$/g, '');
if (!key) throw new Error('TYPESAFE_API_KEY missing from .env');

const git = (...args) => execFileSync('git', args, { cwd: repo, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
const cap = (s, n) => (s.length > n ? s.slice(0, n) + `\n…[truncated ${s.length - n} chars]` : s);

let inTok = 0, outTok = 0, calls = 0;
async function judge(state, questions) {
    const res = await fetch('https://api.typesafe.ai/v1/systemone', {
        method: 'POST',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'jev-latest', state, questions }),
        signal: AbortSignal.timeout(120_000),
    });
    const body = await res.text();
    if (!res.ok) throw new Error(`TypeSafe HTTP ${res.status}: ${body.slice(0, 300)}`);
    const json = JSON.parse(body);
    calls++; inTok += json.usage?.input_tokens ?? 0; outTok += json.usage?.output_tokens ?? 0;
    return json;
}
const noul = (instructions, t, f) => ({ type: 'noul', instructions, criteria: { true: t, false: f } });

// ---- A. /pp branch review ----------------------------------------------------
const BR = 'origin/claude/pp-audit-mode-canonical';
const ppDiff = git('diff', `origin/main...${BR}`, '--', '.agent/workflows/pp.md', '.claude/commands/pp.md', 'AGENTS.md', '.agent/skills/pp/SKILL.md', '.agents/skills.json', '.agent/capabilities/registry.json');
const ppFinal = git('show', `${BR}:.agent/workflows/pp.md`);
const adapterFinal = git('show', `${BR}:.claude/commands/pp.md`);
const branchSafety = git('show', 'origin/main:.agent/workflows/branch-safety.md');
const pr939 = git('show', 'a7f4d753d', '--', '.agent/workflows/pp.md');

const A = await judge(
    { task: 'Review a docs-only branch that reworks the /pp (Perfect Primitive) agent workflow.', branchDiff: cap(ppDiff, 30000), finalPpMd: cap(ppFinal, 20000), finalClaudeAdapter: adapterFinal, branchSafetyPolicyOnMain: branchSafety, earlierMainCommit939: pr939 },
    {
        preserves_939: noul('Does the final pp.md keep the delivery semantics that commit #939 introduced (deliver via /end and /ci-validate, isolated checkout from origin/main allowed when the shared checkout is occupied, read branch-safety.md which defines Entire delivery)?', 'The #939 delivery semantics are preserved.', 'The branch reverts or contradicts #939 delivery semantics.'),
        internally_consistent: noul('Is the final pp.md free of contradictory instructions (e.g. two different delivery rules, or one section forbidding what another requires)?', 'No contradictions found.', 'pp.md contains contradictory instructions.'),
        consistent_with_branch_safety: noul('Are pp.md and the Claude adapter consistent with branch-safety.md (task branches from origin/main, push through Entire origin, owner handles CI/merge)? Flag anything that tells agents to push directly to main or to use GitHub PRs.', 'Consistent with branch-safety.md.', 'Conflicts with branch-safety.md.'),
        adapter_faithful: noul('Is the Claude adapter a faithful thin pointer to the canonical pp.md without introducing rules that pp.md lacks or contradicts?', 'The adapter is faithful.', 'The adapter adds or contradicts rules.'),
        agents_md_minimal: noul('In the AGENTS.md hunk, is the only change the /pp alias wording (no policy changes)?', 'Only the alias wording changed.', 'AGENTS.md also changes policy.'),
        quality: { type: 'score', instructions: 'Rate the clarity and correctness of the final pp.md as agent instructions, 0 (unusable) to 1 (excellent).' },
    },
);

// ---- B. Meeting Rooms working tree superseded by #1056 -----------------------
const BK = 'refs/backup/pre-1056-meeting-rooms-wt';
const files = ['packages/renderer/src/services/agent/orchestration/MeetingRoomOrchestrator.ts', 'packages/renderer/src/services/agent/BaseAgent.ts', 'packages/renderer/src/services/agent/orchestration/BoardroomActionPlan.ts', 'packages/renderer/src/services/agent/components/ContextPipeline.ts', 'packages/renderer/src/services/agent/memory/MeetingRoomMemoryIsolation.test.ts', 'packages/renderer/src/modules/meeting-rooms/MeetingRoomsModule.tsx'];
const residual = git('diff', '265f3a37d', BK, '--', ...files);
const flushLog = git('log', 'origin/main', '--format=%h %s', '-S', 'flushSyncMessage', '-3', '--', 'packages/renderer/src/services/agent');
const flush1039 = git('show', '122f97f9e', '--stat', '--format=%h %s%n%b');
const B = await judge(
    { task: 'A stale uncommitted working tree (based on an old main) contained a Meeting Rooms feature. PR #1056 (commit 265f3a37d) later merged Meeting Rooms to main. Below: diff FROM the merged #1056 version TO the stale working tree for the files with the largest residuals. Lines starting "-" exist in #1056/main; "+" exist only in the stale tree.', residualDiff: cap(residual, 45000), commitsTouchingFlushSyncMessage: flushLog, commit1039Summary: cap(flush1039, 4000) },
    {
        residual_is_drift_only: noul('Are the residual differences explained by main-side evolution (alias import refactor to "@/", code added to main after the stale base, or deliberate removal in a later hardening PR) rather than Meeting Rooms functionality that exists ONLY in the stale tree and is missing from main?', 'Residuals are drift; nothing unique is lost.', 'The stale tree contains Meeting Rooms functionality missing from main.'),
        flush_removal_intentional: noul('Does the evidence indicate flushSyncMessage was intentionally removed/replaced on main (e.g. by the #1039 orchestration hardening) rather than accidentally dropped?', 'Removal looks intentional.', 'Removal looks accidental or unexplained.'),
        unique_items: { type: 'choice', instructions: 'Which best describes any "+" lines unique to the stale tree that main lacks?', criteria: { none: 'None — all explained by drift', imports_only: 'Only import-path style', flush_only: 'Only the flushSyncMessage calls', real_feature: 'Real behaviour missing from main' } },
    },
);

// ---- C. Local main commit superseded by #938 ---------------------------------
const draftVs938 = git('diff', 'ee6703947', 'e02017c8d', '--', ...git('show', '--name-only', '--format=', 'ee6703947').trim().split('\n'));
const C = await judge(
    { task: 'A local-only main commit ee6703947 "fix(boardroom): preserve prompt and reuse recommendations" was never pushed. Squash PR #938 (e02017c8d, same day) merged to main. Diff FROM the local commit TO #938 for the local commit\'s files ("-" only in local commit, "+" only in #938).', diff: cap(draftVs938, 45000) },
    {
        superseded: noul('Is the local commit fully superseded by #938 (anything "-" only in the local commit is an earlier draft that #938 replaced, not a distinct fix)?', 'Superseded; safe to drop.', 'The local commit contains a distinct change #938 lacks.'),
    },
);

const out = { A: A.answers ?? A, B: B.answers ?? B, C: C.answers ?? C, calls, inputTokens: inTok, outputTokens: outTok };
console.log(JSON.stringify(out, null, 2));

