import subprocess,re,hashlib,collections
files=[f for f in subprocess.run(['git','ls-files','packages/renderer/src','packages/firebase/src','packages/shared/src','packages/main/src'],capture_output=True,text=True).stdout.split('\n') if re.search(r'\.(ts|tsx)$',f) and not re.search(r'\.(test|spec)\.|__tests__|/test/|\.d\.ts$',f)]
W=10
win=collections.defaultdict(list); total=0
norm={}
for f in files:
    try: L=open(f,errors='ignore').read().split('\n')
    except: continue
    n=[re.sub(r'\s+',' ',l).strip() for l in L]
    keep=[(i,l) for i,l in enumerate(n) if l and not l.startswith(('import ','//','*','/*','}','{')) and len(l)>3]
    total+=len(keep)
    for k in range(len(keep)-W+1):
        h=hashlib.md5('\n'.join(x[1] for x in keep[k:k+W]).encode()).hexdigest()
        win[h].append((f,keep[k][0]))
dup=collections.defaultdict(set)
pairs=collections.Counter()
for h,locs in win.items():
    if len(locs)>1:
        for f,i in locs[1:]:
            for j in range(W): dup[f].add(i+j)
        fs=sorted(set(f for f,_ in locs))
        if len(fs)>1: pairs[tuple(fs[:2])]+=1
d=sum(len(v) for v in dup.values())
print(f"files={len(files)} meaningful_lines={total} duplicated_lines(>=10-line clones)={d} ({100*d/total:.1f}%)")
for (a,b),c in pairs.most_common(20): print(c, a, '<->', b)
EOF

