                    </div>
                    {event.comment && (
                      <p className="text-sm text-slate-300 mt-2 bg-slate-800/50 p-3 rounded-md border border-slate-700">
                        "{event.comment}"
                      </p>
                    )}
                    <div className="mt-2 text-xs text-slate-500 truncate">
                      {event.actionContext.contentSummary}
                    </div>
