import { useShallow } from 'zustand/react/shallow';
import { RefreshCw, ShieldCheck, ShieldAlert } from 'lucide-react';
import { cn } from '@/lib/utils';
import { motion } from 'motion/react';

export interface SidecarStatusProps {
    collapsed?: boolean;
}

export const SidecarStatus: React.FC<SidecarStatusProps> = ({ collapsed }) => {
    const { sidecarStatus, triggerSidecarRestart } = useStore(
        useShallow((state) => ({
            sidecarStatus: state.sidecarStatus,
            triggerSidecarRestart: state.triggerSidecarRestart,
        }))
    );


    const config = {
        online: {
            icon: ShieldCheck,
            color: 'text-green-500',
            bg: 'bg-green-500/10',
            label: 'Sidecar Online'
        },
        offline: {
            icon: ShieldAlert,
            color: 'text-rose-500',
            bg: 'bg-rose-500/10',
            label: 'Sidecar Offline'
        },
        checking: {
            icon: RefreshCw,
            color: 'text-amber-500',
            bg: 'bg-amber-500/10',
            label: 'Checking...'
        },
        // Item 404: restarting state surfaced from Electron auto-restart logic
        restarting: {
            icon: RefreshCw,
            color: 'text-blue-400',
            bg: 'bg-blue-400/10',
            label: 'Restarting…'
        }
